27	// 1-based number of the node-file write that must return an error; every
28	// other write performs the real atomic persistence. It returns a pointer to
29	// the number of writes actually attempted.
30	func persistFault(t *testing.T, failOnCall int) *int {
31		t.Helper()
32		calls := 0
33		orig := writeNodeFile
34		writeNodeFile = func(path string, records []Heartbeat) error {
35			calls++
36			if calls == failOnCall {
