2	
3	// Regression coverage for the "duplicate-only node file is never re-saved"
4	// guarantee during post-reconnect backfill.
5	//
6	// A batch made entirely of records a node already saved must not rewrite that
7	// node's file: the lock is taken and the saved history is read and verified
8	// exactly as usual, but when every incoming record for a node is a duplicate
9	// the persist stage skips the node entirely. Re-writing identical bytes would
10	// produce the same history and the duplicate counts, so before/after content
11	// comparison alone cannot protect the rule — the avoidable failure this guards
12	// against is a redundant rewrite (temp file, fsync, rename) hitting an I/O
13	// error at exactly the wrong moment and turning a harmless retransmit into a
14	// failed submit. These tests therefore watch the persistence boundary itself:
15	// the package-level writeNodeFile seam records every attempted node-file write
16	// and can deterministically make one node's rewrite fail, with no disk filling,
17	// permission tricks or file-time waiting.
18	//
19	// The guarantee is narrower than "skip the node": identity/content checks are
20	// NOT skipped. Same node+seq with different content is still a conflict, and a
21	// corrupt or foreign-owned saved file is still a corruption error; both reject
22	// the whole batch with new=0 duplicate=0 before anything is persisted.
23	
24	import (
25		"errors"
26		"os"
27		"path/filepath"
28		"strings"
29		"testing"
30		"time"
31	)
32	
33	// errInjectedRewrite stands in for "this node file cannot be re-saved right
34	// now" (disk full, I/O error, ...).
35	var errInjectedRewrite = errors.New("injected node-file rewrite failure")
36	
37	// persistWriteSpy temporarily replaces writeNodeFile. It counts every
38	// persistence attempt and records the target paths; when failPath is non-empty,
39	// a write targeting exactly that path returns errInjectedRewrite instead of
40	// running the real atomic write, while every other node writes for real. The
41	// returned counter survives across the closure and is read after Submit.
42	func persistWriteSpy(t *testing.T, failPath string) (*int, *[]string) {
43		t.Helper()
44		calls := 0
45		paths := []string{}
46		orig := writeNodeFile
47		writeNodeFile = func(path string, records []Heartbeat) error {
48			calls++
49			paths = append(paths, path)
50			if failPath != "" && path == failPath {
51				return errInjectedRewrite
52			}
53			return orig(path, records)
54		}
55		t.Cleanup(func() { writeNodeFile = orig })
56		return &calls, &paths
57	}
58	
59	// writesTo reports how many recorded writes targeted path.
60	func writesTo(paths *[]string, path string) int {
61		n := 0
62		for _, p := range *paths {
63			if p == path {
64				n++
65			}
66		}
67		return n
68	}
69	
70	// fileSnapshot reads a file's exact bytes, failing the test if it is gone.
71	func fileSnapshot(t *testing.T, path string) string {
72		t.Helper()
73		b, err := os.ReadFile(path)
74		if err != nil {
75			t.Fatalf("snapshot %s: %v", path, err)
76		}
77		return string(b)
78	}
79	
80	// reopenStore closes nothing (stores hold no persistent handles) and returns a
81	// fresh instance on dir, so the exercise reads saved history from disk rather
82	// than from any in-memory state the setup used.
83	func reopenStore(t *testing.T, dir string) *Store {
84		t.Helper()
85		s, err := OpenStore(dir)
86		if err != nil {
87			t.Fatal(err)
88		}
89		return s
90	}
91	
92	// TestSubmitAllDuplicateBatchSkipsNodeFileRewrite is the primary regression:
93	// every input record already exists for the node, so the submit must succeed
94	// with new=0, duplicate counted per input occurrence, no extra history row,
95	// and — the point the history assertions alone cannot make — zero calls to the
96	// node-file writer. Byte-identical content after the submit is only a
97	// secondary witness; the write counter is what proves no rewrite happened.
98	func TestSubmitAllDuplicateBatchSkipsNodeFileRewrite(t *testing.T) {
99		dir := t.TempDir()
100		receive := testBase
101		saved := []Heartbeat{
102			hb("dup-node", 1, receive.Add(-2*time.Minute), "1.0", 100, 0),
103			hb("dup-node", 2, receive.Add(-time.Minute), "1.0", 101, 1),
104		}
105		if _, _, err := reopenStore(t, dir).Submit(saved, receive); err != nil {
106			t.Fatal(err)
107		}
108	
109		// A fresh store: duplicate detection must work from durably saved history.
110		store := reopenStore(t, dir)
111		path := store.nodePath("dup-node")
112		before := fileSnapshot(t, path)
113	
