150		before := fileSnapshot(t, loc.path)
151		writes, paths := persistWriteSpy(t, loc.path)
152	
153		newC, dupC, err := store.Submit([]Heartbeat{rec, rec}, receive)
154		if err != nil {
155			t.Fatalf("duplicates need no re-save, so a failing rewrite must not fail the submit: %v", err)
156		}
