179	// TestSubmitDuplicateOnlyNodeNeverBlocksOtherNode pins the mixed reconnect
180	// batch: one node only re-sends records it already has (and its file currently
181	// cannot be re-saved), while another node in the same batch reports a genuine
182	// new record. The duplicate-only node must not be written at all, so it cannot
183	// drag the other node's legitimate submit down. Both storage layouts — the
184	// legacy nodes/hex name and the fixed-length slots/ hash name — must follow
185	// exactly this rule; a long id must neither be treated as a new node nor skip
186	// the ordinary per-node load.
187	func TestSubmitDuplicateOnlyNodeNeverBlocksOtherNode(t *testing.T) {
188		receive := testBase
189		longA := strings.Repeat("a", 126)  // slots/ layout
190		longHan := strings.Repeat("汉", 42) // slots/ layout (multi-byte)
191		longC := strings.Repeat("c", 126)
192	
193		cases := []struct {
194			name          string
195			dupNode       string
196			dupUsesSlot   bool
197			other         string
198			otherUsesSlot bool
199		}{
200			{"legacy name duplicate node, legacy name new node", "dup-node", false, "other-node", false},
201			{"slot duplicate node, legacy name new node", longA, true, "other-node", false},
202			{"legacy name duplicate node, slot new node", "dup-node", false, longC, true},
203			{"slot duplicate node (hanzi), slot new node", longHan, true, strings.Repeat("d", 126), true},
204		}
205		for _, tc := range cases {
206			t.Run(tc.name, func(t *testing.T) {
207				dir := t.TempDir()
208				dupRec := hb(tc.dupNode, 1, receive.Add(-time.Minute), "1.0", 100, 0)
209				if _, _, err := reopenStore(t, dir).Submit([]Heartbeat{dupRec}, receive); err != nil {
210					t.Fatal(err)
211				}
212	
213				store := reopenStore(t, dir)
214				dupLoc := store.nodeLocationFor(tc.dupNode)
215				otherLoc := store.nodeLocationFor(tc.other)
216				if tc.dupUsesSlot && filepath.Dir(dupLoc.path) != store.slotsDir {
217					t.Fatalf("test setup: dup node %q must use a slot, got %s", tc.dupNode, dupLoc.path)
218				}
219				if !tc.dupUsesSlot && filepath.Dir(dupLoc.path) != store.nodesDir {
220					t.Fatalf("test setup: dup node %q must use a legacy name, got %s", tc.dupNode, dupLoc.path)
221				}
222				if tc.otherUsesSlot && filepath.Dir(otherLoc.path) != store.slotsDir {
223					t.Fatalf("test setup: other node %q must use a slot, got %s", tc.other, otherLoc.path)
224				}
225				dupBefore := fileSnapshot(t, dupLoc.path)
226	
227				// The duplicate node's rewrite is "temporarily failing"; the same
228				// batch carries the other node's first, legitimate record. The
229				// duplicate record is sent twice on purpose to pin occurrence
230				// counting under the mixed condition.
231				writes, paths := persistWriteSpy(t, dupLoc.path)
232				otherRec := hb(tc.other, 1, receive.Add(-30*time.Second), "1.0", 200, 2)
233				newC, dupC, err := store.Submit([]Heartbeat{dupRec, dupRec, otherRec}, receive)
234				if err != nil {
235					t.Fatalf("the duplicate-only node must not block the other node's legal submit: %v", err)
236				}
237				if newC != 1 || dupC != 2 {
238					t.Errorf("new=%d duplicate=%d, want new=1 duplicate=2", newC, dupC)
239				}
240				if *writes != 1 || writesTo(paths, dupLoc.path) != 0 {
241					t.Fatalf("exactly one write (the new node's file) must be attempted, got %d: %v", *writes, *paths)
242				}
243				if (*paths)[0] != otherLoc.path {
244					t.Fatalf("the sole write must target the new node %s, got %s", otherLoc.path, (*paths)[0])
245				}
246	
247				// The other node's new heartbeat is really on disk and queryable;
248				// the duplicate node's whole history is exactly as it was.
249				assertHistory(t, dir, tc.other, []Heartbeat{otherRec})
250				assertHistory(t, dir, tc.dupNode, []Heartbeat{dupRec})
251				if got := fileSnapshot(t, dupLoc.path); got != dupBefore {
252					t.Errorf("duplicate-only node file was rewritten:\nbefore=%q\nafter =%q", dupBefore, got)
253				}
254			})
255		}
256	}
